const queues={};let pending=0;
function setSync(){const d=$('#syncdot'),t=$('#synctxt');if(!d)return;d.className='dot'+(pending?' busy':'');t.textContent=pending?'Menyimpan…':'Tersimpan'}
function enqueue(key,job){pending++;setSync();queues[key]=(queues[key]||Promise.resolve()).then(job).catch(e=>{toast('Gagal menyimpan. Coba lagi.');console.error(e)}).then(()=>{pending--;setSync()})}
function writeItems(key,obj){
  const ref=DB.doc('wp/'+key);
  return exists[key]?ref.update({items:obj}):ref.set({items:obj}).then(()=>{exists[key]=true});
}
function putItem(key,item){D[key]=D[key]||{};D[key][item.id]=item;render();enqueue(key,()=>writeItems(key,{[item.id]:item}))}
function putMany(key,items){D[key]=D[key]||{};const o={};items.forEach(i=>{D[key][i.id]=i;o[i.id]=i});render();enqueue(key,()=>writeItems(key,o))}
function delItem(key,id){delete D[key][id];render();enqueue(key,()=>DB.doc('wp/'+key).set({items:JSON.parse(JSON.stringify(D[key]))}).then(()=>{exists[key]=true}))}
function putSettings(p){D.settings=Object.assign({},D.settings,p);render();enqueue('settings',()=>exists.settings?DB.doc('wp/settings').update(p):DB.doc('wp/settings').set(D.settings).then(()=>{exists.settings=true}))}
