function calc(){
  const budget=L('budget'),exp=L('expenses'),ven=L('vendors'),gs=L('guests'),gifts=L('gifts'),cl=L('checklist');
  const isPaid=e=>paidOf(e)>0;
  const paidB={},actB={},paidV={};
  exp.forEach(e=>{const a=+e.amount||0;if(e.budgetId){actB[e.budgetId]=(actB[e.budgetId]||0)+a;paidB[e.budgetId]=(paidB[e.budgetId]||0)+paidOf(e)}if(e.vendorId)paidV[e.vendorId]=(paidV[e.vendorId]||0)+paidOf(e)});
  const bIds=new Set(budget.map(b=>b.id));
  const linked=g=>g.budgetId&&bIds.has(g.budgetId);
  const gAct=g=>linked(g)?(actB[g.budgetId]||0):(+g.actual||0);
  const unl=gifts.filter(g=>!linked(g));
  const bt=b=>(+b.qty||1)*(+b.price||0);
  const expAll=sum(exp,e=>e.amount),expPaid=sum(exp,paidOf);
  const giftAct=sum(unl,gAct);
  const estRun=sum(budget.filter(b=>actB[b.id]>0),bt)+sum(unl.filter(g=>gAct(g)>0),g=>g.est);
  const plan=sum(budget,bt), actual=expAll, paid=expPaid, bill=expAll-expPaid;
  const sv=L('savings');const signed=s=>s.type==='Penarikan'?-s.amount:+s.amount;
  const saldo=sum(sv,signed),saldoA=sum(sv.filter(s=>s.who===nameA()),signed),saldoB=sum(sv.filter(s=>s.who===nameB()),signed);
  const hadir=gs.filter(g=>g.rsvp==='Hadir'),tidak=gs.filter(g=>g.rsvp==='Tidak Hadir'),belum=gs.filter(g=>g.rsvp!=='Hadir'&&g.rsvp!=='Tidak Hadir');
  const bought=gifts.filter(g=>g.status==='Sudah Dibeli');
  return {budget,exp,ven,gs,gifts,unl,linked,gAct,paidB,actB,paidV,bt,isPaid,plan,actual,paid,bill,sisa:plan-actual,selisih:estRun-actual,
    saldo,saldoA,saldoB,sv,hadir,tidak,belum,hadirOrang:sum(gs,confOf),paxAll:sum(gs,g=>g.pax),
    sent:gs.filter(g=>g.invited==='Sudah').length,
    clDone:cl.filter(c=>stOf(c)==='Selesai').length,clProc:cl.filter(c=>stOf(c)==='Dalam Proses').length,clAll:cl.length,
    gEst:sum(gifts,g=>g.est),gActAll:sum(gifts,gAct),gBought:bought.length};
}
const payStatus=(paid,total)=>paid<=0?['Belum','']:paid>total&&total>0?['Melebihi','bad']:paid>=total&&total>0?['Lunas','ok']:['DP','warn'];
function allocRows(c){
  const cats=catNames();
  const rows=cats.map(cat=>{const items=c.budget.filter(b=>b.cat===cat),ids=new Set(items.map(b=>b.id)),trx=c.exp.filter(e=>ids.has(e.budgetId));
    return {cat,n:items.length,t:trx.length,est:sum(items,c.bt),act:sum(trx,e=>e.amount)}});
  const np=c.exp.filter(e=>!e.budgetId||!c.budget.some(b=>b.id===e.budgetId));
  if(np.length)rows.push({fixed:1,cat:'Realisasi tanpa item',n:0,t:np.length,est:0,act:sum(np,e=>e.amount)});
  return rows;
}
function forecast(c){
  const s=S(),target=+s.target||0;
  const keys=c.sv.map(x=>(x.date||'').slice(0,7)).filter(Boolean).sort();
  if(!keys.length)return {none:true};
  const [fy,fm]=keys[0].split('-').map(Number),n=new Date();
  const active=Math.max(1,(n.getFullYear()-fy)*12+(n.getMonth()+1-fm)+1);
  const avg=c.saldo/active;
  if(c.saldo>=target)return {done:true,avg};
  if(avg<=0)return {avg,none:true};
  const need=Math.ceil((target-c.saldo)/avg),eta=new Date(n.getFullYear(),n.getMonth()+need,1);
  let late=0;if(s.weddingDate){const w=new Date(s.weddingDate+'T00:00:00');late=(eta.getFullYear()-w.getFullYear())*12+eta.getMonth()-w.getMonth()}
  return {avg,need,eta,late};
}

