function bnDonut(segs,tot,c1,c2,label){
  const R=52,C=2*Math.PI*R;let acc=0;
  const arcs=tot>0?segs.filter(a=>a.v>0).map(a=>{const len=a.v/tot*C,s=`<circle cx="70" cy="70" r="${R}" fill="none" stroke="${a.col}" stroke-width="20" stroke-dasharray="${len.toFixed(2)} ${(C-len).toFixed(2)}" stroke-dashoffset="${(-acc).toFixed(2)}" transform="rotate(-90 70 70)"/>`;acc+=len;return s}).join(''):'';
  return `<svg class="bn-donut" viewBox="0 0 140 140" role="img" aria-label="${esc(label)}"><circle cx="70" cy="70" r="${R}" fill="none" stroke="rgba(140,83,98,.10)" stroke-width="20"/>${arcs}<text x="70" y="${c2?66:74}" text-anchor="middle" class="bn-dt1">${esc(c1)}</text>${c2?`<text x="70" y="84" text-anchor="middle" class="bn-dt2">${esc(c2)}</text>`:''}</svg>`;
}
