function placeSheet(id){
  const p=byId('invest',id);if(!p){closeSheet();return}
  const st=pStatus(p),rd=redOf(p),rem=remOf(p),par=fromRed(p)?byId('invest',p.src.pid):null;
  const kv=(a,b)=>`<div class="kv"><span>${a}</span><b>${b}</b></div>`;
  openPanel(`<h2>${esc(p.name)}</h2><div style="display:flex;gap:6px;flex-wrap:wrap;margin:-6px 0 12px"><span class="pill ${PST[st]}">${st}</span><span class="pill">${esc(p.kind)}</span><span class="pill">${esc(p.owner||'Bersama')}</span></div>
   ${kv('Nominal penempatan',fmt(p.amount))}${rd.length?kv('Pokok yang sudah dicairkan',fmt(p.amount-rem))+kv('Sisa penempatan',fmt(rem)):''}${kv('Tanggal penempatan',p.date?dFmt(p.date):'-')}${kv('Jatuh tempo',p.due?dFmt(p.due)+(tenor(p.date,p.due)?' · '+tenor(p.date,p.due):''):'-')}${kv('Sumber dana',par?'Pencairan '+esc(par.name):'Tabungan')}${kv('Imbal hasil',yTxt(yieldOf(p)))}${rem>0&&+p.gain?kv('  termasuk belum dicairkan',sgn(+p.gain)):''}${p.note?kv('Keterangan',esc(p.note)):''}
   <div class="sec" style="margin:18px 0 8px"><h2 style="font-size:20px">Riwayat pencairan</h2></div>
   ${rd.length?rd.map(r=>{const to=r.dest==='Instrumen'?((byId('invest',r.destPid)||{}).name||'instrumen lain'):(r.destAcct||'Tabungan'),ask=UI.tb.undo===r.id;
     return `<div class="txn" style="cursor:default;display:block"><div style="display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap"><b>${dFmt(r.date)}</b><b class="num">${fmt(r.total)}</b></div><div>Pokok ${fmt(r.principal)} · imbal hasil ${sgn(+r.yield||0)}</div><div>${r.dest==='Instrumen'?'Dialihkan ke':'Dikembalikan ke'} <b>${esc(to)}</b>${r.note?' · '+esc(r.note):''}</div>${canWrite?`<div style="margin-top:6px"><button class="btn sm ${ask?'danger':'bad'}" data-act="redUndo" data-id="${p.id}" data-rid="${r.id}">${ask?'Ya, batalkan pencairan ini':'Batalkan pencairan'}</button></div>`:''}</div>`}).join(''):'<div class="note">Belum ada pencairan.</div>'}
   <div class="acts"><button class="btn" data-act="closeSheet">Tutup</button>${canWrite?`<button class="btn" data-act="editPlace" data-id="${p.id}">Ubah</button>${rem>0?`<button class="btn pri" data-act="addRedeem" data-id="${p.id}">Catat pencairan</button>`:''}`:''}</div>`);
}
function placeMenu(id){
  const p=byId('invest',id);if(!p)return;const rem=remOf(p),b=(a,i,l)=>`<a href="#" data-act="${a}" data-id="${id}">${ic(i)}${l}</a>`;
  openPanel(`<h2>${esc(p.name)}</h2><div class="moregrid">${b('pview','eye','Lihat detail dan riwayat pencairan')}${b('editPlace','pencil','Ubah penempatan atau perbarui status dan nilai')}${rem>0?b('addRedeem','arrowsLR','Catat pencairan'):''}</div><div class="acts"><button class="btn" data-act="closeSheet">Tutup</button></div>`);
}

function redeemUi(form,rem){
  const g=k=>form.elements[k],num=v=>+String(v).replace(/[^\d-]/g,'')||0,wrap=k=>g(k).closest('.fld');
  g('total').readOnly=true;
  const sync=()=>{const t=num(g('principal').value)+num(g('yield').value);g('total').value=t>0?Math.round(t).toLocaleString('id-ID'):''};
  const dest=()=>{const i=g('dest').value==='Instrumen';['destKind','destName','destDue'].forEach(k=>{wrap(k).hidden=!i});wrap('destAcct').hidden=i};
  g('principal').addEventListener('input',sync);g('yield').addEventListener('input',sync);g('dest').addEventListener('change',dest);sync();dest();
}

