function vCatatan(){
  const all=L('notes'),f=UI.ct,open=all.filter(n=>n.status!=='Selesai'),late=open.filter(n=>n.due&&n.due<todayISO());
  const pics=[...new Set(all.map(n=>n.pic))];
  const items=all.filter(n=>(f.st==='Semua'||(f.st==='Open')===(n.status!=='Selesai'))&&(f.pic==='Semua'||n.pic===f.pic)&&(f.type==='Semua'||noteType(n)===f.type)&&hit(f.q,n.topic,n.note,n.follow)).sort((a,b)=>(a.status==='Selesai')-(b.status==='Selesai')||(a.due||'9').localeCompare(b.due||'9'));
  return head('Catatan','Ide, hasil diskusi, keputusan keluarga, dan yang perlu dibahas',addBtn('addNote','Tambah catatan'))+
  `<div class="grid g4" style="margin-bottom:16px">${tile('Total',all.length)}${tile('Terbuka',open.length)}${tile('Selesai',all.length-open.length,'',pct(all.length-open.length,all.length),'ok')}${tile('Punya tenggat',open.filter(n=>n.due).length)}</div>
  <div class="chips">${['Semua',...NTYPES].map(t=>`<button class="chip" aria-pressed="${f.type===t}" data-act="ctType" data-v="${esc(t)}">${t}${t!=='Semua'?`<em>${all.filter(n=>noteType(n)===t).length}</em>`:''}</button>`).join('')}</div>
  <div class="tools">${searchBox('ct','Cari catatan')}<div class="seg">${[['Open','Terbuka'],['Selesai','Selesai'],['Semua','Semua']].map(([v,l])=>`<button aria-pressed="${f.st===v}" data-act="ctSt" data-v="${v}">${l}</button>`).join('')}</div>
  <div class="seg">${['Semua',...pics].map(p=>`<button aria-pressed="${f.pic===p}" data-act="ctPic" data-v="${esc(p)}">${esc(p)}</button>`).join('')}</div></div>
  <div class="grid g2 top">${items.map(n=>`<article class="card ${n.status==='Selesai'?'done':''}"><div style="display:flex;gap:12px;align-items:flex-start"><button class="cb" role="checkbox" aria-checked="${n.status==='Selesai'}" aria-label="Tandai selesai" data-act="toggleNote" data-id="${n.id}" style="margin-top:2px">${ic('tick',2.4)}</button><div class="main click" data-act="editNote" data-id="${n.id}" style="flex:1;min-width:0;cursor:pointer"><div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center"><span class="eyebrow">${esc(n.topic)}</span><span class="pill acc">${esc(noteType(n))}</span></div><div class="t" style="font-weight:500;margin-top:4px">${esc(n.note)}</div>${n.follow?`<div class="note" style="margin-top:4px">Tindak lanjut: ${esc(n.follow)}</div>`:''}<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px;align-items:center"><span class="note">${esc(n.pic)}</span>${priPill(n.pri)}${n.status!=='Selesai'?dueTag(n.due):''}</div></div></div></article>`).join('')}</div>${items.length?'':emptyBox(all.length?'Tidak ada catatan':'Belum ada catatan','Tulis ide, hasil diskusi, atau keputusan keluarga di sini.',canWrite?`<br><button class="btn pri" data-act="addNote">Tambah catatan</button>`:'')}`;
}

/* ================= forms ================= */
const PEOPLE=()=>[nameA(),nameB(),'Bersama'];
const budgetOpts=()=>[['','— Tanpa item —'],...L('budget').map(b=>[b.id,b.cat+' · '+b.name])];
const vendorOpts=()=>[['','— Tanpa vendor —'],...L('vendors').map(v=>[v.id,v.name])];
async function compress(file){
  if(!file.type.startsWith('image/'))return file;
  try{const bmp=await createImageBitmap(file),s=Math.min(1,1400/Math.max(bmp.width,bmp.height)),cv=document.createElement('canvas');cv.width=Math.round(bmp.width*s);cv.height=Math.round(bmp.height*s);cv.getContext('2d').drawImage(bmp,0,0,cv.width,cv.height);return await new Promise(r=>cv.toBlob(b=>r(b||file),'image/jpeg',.82))}catch(_){return file}
}
function openForm(o){
  const v=o.values||{};
  const fld=f=>{const val=v[f.k]==null?'':v[f.k];let inp;const id='f_'+f.k;
    if(f.t==='select')inp=`<select id="${id}" name="${f.k}">${f.o.map(x=>{const [a,b]=Array.isArray(x)?x:[x,x];return `<option value="${esc(a)}" ${String(val)===String(a)?'selected':''}>${esc(b)}</option>`}).join('')}</select>`;
    else if(f.t==='area')inp=`<textarea id="${id}" name="${f.k}">${esc(val)}</textarea>`;
    else if(f.t==='money')inp=`<input id="${id}" name="${f.k}" type="text" inputmode="numeric" value="${val===''?'':Math.round(val).toLocaleString('id-ID')}" data-money autocomplete="off">`;
    else if(f.t==='num')inp=`<input id="${id}" name="${f.k}" type="text" inputmode="numeric" value="${esc(val)}" autocomplete="off">`;
    else if(f.t==='attach')inp=`<div class="attach"><input id="${id}" name="${f.k}" type="text" value="${esc(val)}" placeholder="Tempel link${ASSETS?' atau unggah berkas':''}" autocomplete="off">${ASSETS?`<label class="btn sm">Unggah<input type="file" accept="${f.img?'image/*':'image/*,application/pdf'}" data-up="${f.k}" hidden></label>`:''}</div>${f.img?`<img class="thumb" id="th_${f.k}" src="${esc(val)}" alt="" ${val?'':'hidden'}>`:''}`;
    else inp=`<input id="${id}" name="${f.k}" type="${f.t||'text'}" value="${esc(val)}" ${f.list?`list="dl_${f.k}"`:''} ${f.t==='tel'?'inputmode="tel"':''} autocomplete="off">${f.list?`<datalist id="dl_${f.k}">${f.list.map(x=>`<option value="${esc(x)}">`).join('')}</datalist>`:''}`;
    return `<div class="fld"><label for="${id}">${f.l}</label>${inp}${f.hint?`<span class="note">${f.hint}</span>`:''}</div>`};
  const body=[];for(let i=0;i<o.fields.length;i++){const f=o.fields[i];if(f.half&&o.fields[i+1]&&o.fields[i+1].half){body.push(`<div class="frow">${fld(f)}${fld(o.fields[i+1])}</div>`);i++}else body.push(fld(f))}
  const sh=$('#sheet');
  sh.innerHTML=`<div class="sbg" data-act="closeSheet"></div><form class="panel" id="form" role="dialog" aria-modal="true" aria-label="${esc(o.title)}" novalidate><h2>${esc(o.title)}</h2>${body.join('')}
   <div class="confirm" id="conf" hidden><p>Hapus data ini? Tindakan ini tidak bisa dibatalkan.</p><div class="acts" style="margin-top:10px"><button type="button" class="btn" data-act="fdelNo">Batal</button><button type="button" class="btn danger" data-act="fdelOk">Ya, hapus</button></div></div>
   <div class="acts" id="acts">${o.del&&canWrite?`<button type="button" class="btn bad sp" data-act="fdel">Hapus</button>`:''}<button type="button" class="btn" data-act="closeSheet">Batal</button>${canWrite?`<button class="btn pri" type="button" data-act="fsave">Simpan</button>`:''}</div></form>`;
  sh.classList.add('on');
  const form=$('#form');
  const doSave=()=>{const out={};
    try{for(const f of o.fields){let x=form.elements[f.k].value.trim();if(f.t==='money'||f.t==='num')x=+x.replace(/[^\d-]/g,'')||0;out[f.k]=x;
      if(f.req&&(x===''||(x===0&&f.t==='money'))){toast('Lengkapi: '+f.l.toLowerCase());form.elements[f.k].focus();return}}
    if(o.save(out)===false)return;closeSheet()}catch(err){console.error(err);toast('Gagal menyimpan: '+err.message)}};
  form._save=doSave;
  form.addEventListener('submit',e=>{e.preventDefault();doSave()});
  form.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.tagName==='INPUT'){e.preventDefault();doSave()}});
  form.addEventListener('input',e=>{if(e.target.dataset.money!==undefined){const d=e.target.value.replace(/\D/g,'');e.target.value=d?(+d).toLocaleString('id-ID'):''}});
  form._del=o.del;
  if(o.onopen)o.onopen(form);
  const first=form.querySelector('input,select,textarea');if(first&&!o.values.id)setTimeout(()=>first.focus(),60);
}
function closeSheet(){const s=$('#sheet');s.classList.remove('on');s.innerHTML=''}
const keep=(...a)=>Object.assign({},...a);
const parseMoney=s=>{s=String(s).trim().toLowerCase().replace(/^rp\.?\s*/,'');const m=/^([\d.,]+)\s*(jt|juta|rb|ribu|k)?$/.exec(s);if(!m)return null;if(m[2]){const n=parseFloat(m[1].replace(',','.'));return Math.round(n*(m[2]==='jt'||m[2]==='juta'?1e6:1e3))}return +m[1].replace(/[.,]/g,'')};
const parseList=txt=>String(txt).split(/\n+/).map(l=>l.trim()).filter(Boolean).map(l=>{const m=/^(.*?)[\s:=\-–]*((?:rp\.?\s*)?\d[\d.,]*\s*(?:jt|juta|rb|ribu|k)?)$/i.exec(l);if(m&&m[1].trim()){const v=parseMoney(m[2]);return {name:m[1].trim(),price:v==null||isNaN(v)?0:v}}return {name:l,price:0}});
