document.addEventListener('click',e=>{
  const el=e.target.closest('[data-act]');if(!el)return;
  const inner=e.target.closest('button[data-act],a[data-act]');
  const tgt=inner&&el.contains(inner)?inner:el,act=tgt.dataset.act;
  if(!A[act])return;
  if(tgt.tagName==='A'&&tgt.getAttribute('href')==='#')e.preventDefault();
  A[act](tgt);
});
document.addEventListener('change',async e=>{
  const el=e.target,d=el.dataset;
  if(d.chg==='rsvp'){const g=byId('guests',d.id);if(g&&canWrite){const conf=el.value==='Hadir'?(confOf(g)||g.pax):0;putItem('guests',keep(g,{rsvp:el.value,confirmed:conf}))}}
  else if(d.chg==='noteDue'||d.chg==='noteTime'){const n=byId('notes',d.id);if(n&&canWrite)putItem('notes',keep(n,d.chg==='noteDue'?{due:el.value}:{dueTime:el.value}))}
  else if(d.chg==='clpic'){UI.cl.pic=el.value;render()}
  else if(d.chg==='clst'){UI.cl.st=el.value;render()}
  else if(d.chg==='tmside'){UI.tm.side=el.value;render()}
  else if(d.chg==='gfst'){UI.gf.st=el.value;render()}
  else if(d.chg==='tbkind'){UI.tb.kind=el.value;render()}
  else if(d.up){
    const f=el.files[0];if(!f||!ASSETS)return;toast('Mengunggah…');
    try{const blob=await compress(f),r=await ASSETS.upload(blob),inp=$('#f_'+d.up);if(inp)inp.value=r.url;const th=$('#th_'+d.up);if(th){th.src=r.url;th.hidden=false}toast('Berkas terunggah')}catch(err){console.error(err);toast('Gagal mengunggah. Coba tempel link.')}
    el.value='';
  }
});
